let kotobaState={view:'list',id:null,q:'',category:'all',sub:'all',source:'all',savedOnly:false,page:1};
function canonicalKotobaId(id){return typeof KOTOBA_N4_MERGED_IDS==='undefined'?id:(KOTOBA_N4_MERGED_IDS[id]||id)}
let kotobaSaved=[];
try{const ids=JSON.parse(localStorage.getItem('gaku-kotoba-saved'));if(Array.isArray(ids))kotobaSaved=[...new Set(ids.filter(x=>typeof x==='string').map(canonicalKotobaId))]}catch{}
function getKotobaRoute(){return {...kotobaState}}
function resetKotobaRoute(){kotobaState={view:'list',id:null,q:'',category:'all',sub:'all',source:'all',savedOnly:false,page:1}}
function restoreKotobaRoute(s){resetKotobaRoute();if(!s)return;s={...s,id:canonicalKotobaId(s.id)};kotobaState.q=typeof s.q==='string'?s.q.slice(0,100):'';kotobaState.category=[...kotobaCategories(prefs.level).map(c=>c.id),'custom'].includes(s.category)?s.category:'all';kotobaState.sub=kotobaSubcategories(kotobaState.category,prefs.level).includes(s.sub)?s.sub:'all';kotobaState.source='all';kotobaState.page=Math.max(1,Math.floor(Number(s.page)||1));kotobaState.savedOnly=s.savedOnly===true;if(allKotobaEntries(prefs.level).some(e=>e.id===s.id)){kotobaState.id=s.id;kotobaState.view=s.view==='detail'?'detail':'list'}}
function rememberKotoba(){if(page==='Kotoba')history.replaceState(appRoute(),'')}
function kotobaResults(){return findKotoba(kotobaState.q,kotobaState.category,kotobaState.sub,kotobaState.source,kotobaState.savedOnly,kotobaSaved,prefs.level)}
function kotobaCategory(id){return kotobaCategories(prefs.level).find(c=>c.id===id)||{name:'Buatanmu',color:'lavender'}}
function kotobaSearchChange(value){kotobaState.q=value.slice(0,100);kotobaState.page=1;refreshKotobaResults();rememberKotoba()}
function kotobaFilter(key,value){kotobaState[key]=value;kotobaState.page=1;if(key==='category')kotobaState.sub='all';rememberKotoba();render()}
function clearKotobaFilters(){resetKotobaRoute();rememberKotoba();render();document.getElementById('kotoba-search').focus()}
function refreshKotobaResults(){const el=document.getElementById('kotoba-results');if(el){el.innerHTML=kotobaResultHTML();enhanceLearningPickers()}}
function changeKotobaPage(n){kotobaState.page=n;refreshKotobaResults();rememberKotoba();document.getElementById('kotoba-results').scrollIntoView({block:'start',behavior:'instant'})}
function openKotoba(id,replace=false){id=canonicalKotobaId(id);if(!allKotobaEntries(prefs.level).some(e=>e.id===id))return;stopAudio();kotobaState.view='detail';kotobaState.id=id;if(replace)rememberKotoba();else pushRoute();updateScreen()}
function saveKotoba(){const id=kotobaState.id;const next=kotobaSaved.includes(id)?kotobaSaved.filter(x=>x!==id):[...kotobaSaved,id];try{localStorage.setItem('gaku-kotoba-saved',JSON.stringify(next))}catch{toast('Belum bisa menyimpan materi. Periksa penyimpanan browser.');return}kotobaSaved=next;const b=document.getElementById('kotoba-save');if(b){b.setAttribute('aria-pressed',String(next.includes(id)));b.textContent=next.includes(id)?'♥ Tersimpan':'♡ Simpan kata'}toast(next.includes(id)?'Kata disimpan di perangkat ini.':'Kata dihapus dari simpanan.')}
function speakKotoba(){const e=allKotobaEntries(prefs.level).find(e=>e.id===kotobaState.id);if(!e)return;const reading=(e.kana||e.jp).replace(/[~〜～]/g,'');speak(reading,{onState(state){const el=document.getElementById('kotoba-audio-state');if(el)el.textContent={loading:'Menyiapkan suara…',playing:'♪ Sedang diputar',done:'Ketuk untuk mengulang',unavailable:'Suara Jepang belum tersedia di perangkat'}[state]||''}})}
function kotobaScreen(){if(kotobaState.view==='detail')return kotobaDetail();const counts=kotobaFilterCounts(kotobaState.category,prefs.level);return title('Kotoba','Satu kata baru, satu dunia yang terbuka.')+`<div class="kotoba-library"><section class="kotoba-intro"><div><span class="kotoba-kicker">ことば · KOSAKATA ${prefs.level==='N4'?'N4 & A2':'N5 & A1'}</span><h2>Kumpulkan kata,<br>rangkai ceritamu.</h2><p>${kotobaBaseEntries(prefs.level).length.toLocaleString('id-ID')} kosakata dan ungkapan. Pilih jenis kata dan tema, temukan artinya, pelajari cara membacanya, dan simpan kata pilihanmu.</p></div><div class="kotoba-art" aria-hidden="true"><span>こ</span><span>と</span><span>ば</span><i>✦</i></div></section>${prefs.level==='N4'?'<details class="kotoba-variants"><summary>Tentang materi N4 / A2</summary><p>Materi Marugoto dan Irodori A2, ditambah 411 kata sisa daftar harian. Tanda ＋ menunjukkan pengayaan yang dapat melampaui N4 dasar.</p></details>':''}<div class="kotoba-toolbar"><label for="kotoba-search" class="kotoba-search-label">Kata apa yang ingin kamu cari?</label><div class="kotoba-searchbox"><span aria-hidden="true">⌕</span><input id="kotoba-search" type="search" autocomplete="off" maxlength="100" value="${esc(kotobaState.q)}" placeholder="Kana, kanji, romaji, atau arti…" oninput="kotobaSearchChange(this.value)"></div><div class="kotoba-filters"><label>Kategori<select aria-label="Kategori Kotoba" onchange="kotobaFilter('category',this.value)"><option value="all">Semua kategori</option>${kotobaCategories(prefs.level).map(c=>`<option value="${c.id}" ${c.id===kotobaState.category?'selected':''}>${c.name} (${counts.categories[c.id]||0})</option>`).join('')}${customData.length?`<option value="custom" ${kotobaState.category==='custom'?'selected':''}>Buatanmu</option>`:''}</select></label><label>Subkategori<select aria-label="Subkategori Kotoba" onchange="kotobaFilter('sub',this.value)"><option value="all">Semua subkategori</option>${kotobaSubcategories(kotobaState.category,prefs.level).map(s=>`<option value="${esc(s)}" ${s===kotobaState.sub?'selected':''}>${esc(s)} (${counts.subcategories[s]||0})</option>`).join('')}</select></label></div><p class="kotoba-taxonomy-hint">Pilih jenis kata, lalu jelajahi tema yang kamu suka.</p><div class="kotoba-filter-bottom"><span>Cari bentuk kamus maupun ～ます, misalnya “taberu” atau “tabemasu”.</span><button class="kotoba-saved-filter" aria-pressed="${kotobaState.savedOnly}" onclick="kotobaFilter('savedOnly',${!kotobaState.savedOnly})">${kotobaState.savedOnly?'♥':'♡'} Tersimpan</button></div></div><div id="kotoba-results" aria-live="polite" aria-atomic="false">${kotobaResultHTML()}</div></div>`}
// One gloss in the list; the detail and search retain the full meaning.
function kotobaListMeaning(e){
 if(e.jp==='おかげさまで')return 'berkat';
 const value=String(e.meaning||'').trim();let depth=0;
 for(let i=0;i<value.length;i++){
  const ch=value[i];if('(<['.includes(ch))depth++;else if(')>]'.includes(ch))depth=Math.max(0,depth-1);
  else if(!depth&&(ch==='/'||ch===';'||ch===','&&e.category!=='expression'&&!(/\d/.test(value[i-1]||'')&&/\d/.test(value[i+1]||''))||ch==='?'&&/\s+\S/.test(value.slice(i+1))))return value.slice(0,i+(ch==='?'?1:0)).trim();
 }
 return value;
}
function kotobaListCard(e){
 const size=Array.from(e.jp).length>10?' kotoba-word-long':Array.from(e.jp).length>6?' kotoba-word-medium':'';
 return `<button class="kotoba-card ${kotobaCategory(e.category).color}" aria-label="Pelajari kata ${esc(e.jp)}: ${esc(kotobaListMeaning(e))}" onclick="openKotoba('${e.id}')"><span class="kotoba-card-top"><span>${esc(e.subcategory)}</span><span class="kotoba-card-open" aria-hidden="true">${kotobaSaved.includes(e.id)?'♥':'›'}</span></span><span class="kotoba-card-body"><span class="kotoba-card-word${size}" lang="ja">${esc(e.jp)}</span></span><span class="kotoba-card-meaning">${esc(kotobaListMeaning(e))}</span></button>`;
}
function kotobaResultHTML(){const p=kotobaPageSlice(kotobaResults(),kotobaState.page);kotobaState.page=p.page;if(!p.total)return `<div class="kotoba-empty"><span>${kotobaState.savedOnly?'♡':'🌱'}</span><h2>${kotobaState.savedOnly?'Belum ada kata yang cocok di simpanan':'Kata belum ditemukan'}</h2><p>Coba “neko”, “ねこ”, “猫”, atau “kucing”. Coba juga tema yang berbeda.</p><button class="primary" onclick="clearKotobaFilters()">Lihat semua kosakata</button></div>`;const start=(p.page-1)*KOTOBA_PAGE_SIZE+1;let nums=[];for(let n=Math.max(1,p.page-2);n<=Math.min(p.totalPages,p.page+2);n++)nums.push(n);return `<div class="kotoba-result-head"><h2>${kotobaState.savedOnly?'Kata tersimpan':kotobaState.category==='all'?'Jelajahi kosakata':kotobaCategory(kotobaState.category).name}</h2><span>${start}–${start+p.items.length-1} dari ${p.total}</span></div><div class="kotoba-grid">${p.items.map(kotobaListCard).join('')}</div><nav class="kotoba-pagination" aria-label="Halaman Kotoba"><button aria-label="Kotoba halaman sebelumnya" ${p.page===1?'disabled':''} onclick="changeKotobaPage(${p.page-1})">‹</button>${p.page>3?'<span>…</span>':''}${nums.map(n=>`<button aria-label="Kotoba halaman ${n}" ${n===p.page?'class="current" aria-current="page"':''} onclick="changeKotobaPage(${n})">${n}</button>`).join('')}${p.page<p.totalPages-2?'<span>…</span>':''}<button aria-label="Kotoba halaman berikutnya" ${p.page===p.totalPages?'disabled':''} onclick="changeKotobaPage(${p.page+1})">›</button></nav><p class="kotoba-page-caption">Halaman ${p.page} / ${p.totalPages} · Maksimal 15 kata per halaman</p><label class="kotoba-page-jump">Ke halaman<select aria-label="Lompat ke halaman Kotoba" onchange="changeKotobaPage(Number(this.value))">${Array.from({length:p.totalPages},(_,i)=>`<option value="${i+1}" ${p.page===i+1?'selected':''}>${i+1}</option>`).join('')}</select></label>`}
function kotobaSourcesForLevel(){return prefs.level==='N4'?KOTOBA_N4_SOURCES:KOTOBA_SOURCES}
function kotobaSenseDetails(e){return !e.senses?.length?'':`<section class="kotoba-example-section kotoba-senses"><span class="kotoba-kicker">BEDAKAN KONTEKSNYA</span><h2>Makna sesuai pemakaian</h2>${e.senses.map(s=>`<div class="kotoba-example"><h3>${esc(s.label)}</h3><p>${esc(s.meaning)}</p>${s.example?`<p lang="ja" class="kotoba-example-jp">${esc(s.example.jp)}</p><p lang="ja" class="kotoba-example-kana">${esc(s.example.kana)}</p><p class="kotoba-example-romaji">${esc(bunpoExampleRomaji(s.example.kana))}</p><p>${esc(s.example.meaning)}</p>`:''}</div>`).join('')}</section>`}
function kotobaDetail(){const e=allKotobaEntries(prefs.level).find(e=>e.id===kotobaState.id);if(!e){kotobaState.view='list';return kotobaScreen()}const saved=kotobaSaved.includes(e.id);const candidates=kotobaResults(),index=candidates.findIndex(x=>x.id===e.id),next=index>=0?candidates[index+1]:null;return `<article class="kotoba-detail"><header class="page-header"><button class="back" aria-label="Kembali ke daftar Kotoba" onclick="appBack()">‹</button><div><div class="eyebrow">${esc(kotobaCategory(e.category).name)} · ${esc(e.subcategory)}</div><h1>Kenali kata</h1></div><span class="kotoba-level">${esc(e.scope)}</span></header><section class="kotoba-word-panel"><span class="kotoba-kicker">KATA PILIHANMU</span><h2 lang="ja">${esc(e.jp)}</h2>${e.kana?`<p lang="ja" class="kotoba-word-kana">${esc(e.kana)}</p>`:''}<p class="kotoba-word-romaji">${esc(e.romaji)}</p><div class="kotoba-word-meaning">${esc(e.meaning)}</div><button class="kotoba-sound" aria-label="Dengarkan kata ${esc(e.jp)}" onclick="speakKotoba()">♪ <span>Dengarkan kata</span></button><small id="kotoba-audio-state" role="status">Suara bahasa Jepang di perangkat</small></section><div class="kotoba-detail-tools"><button id="kotoba-save" aria-pressed="${saved}" onclick="saveKotoba()">${saved?'♥ Tersimpan':'♡ Simpan kata'}</button>${e.category==='custom'?'<span>Buatanmu</span>':''}</div>${e.polite?`<section class="kotoba-forms"><h2>Dua bentuk, satu kata</h2><div><span>Bentuk kamus<strong lang="ja">${esc(e.jp)}</strong><small>${esc(e.romaji)}</small></span><i aria-hidden="true">↔</i><span>Bentuk sopan<strong lang="ja">${esc(e.polite.jp)}</strong><small>${esc(kanjiRomanize(e.polite.kana))}</small></span></div><p>Kata kerja grup ${e.group}. Kedua bentuk bisa dipakai untuk mencari kata ini.</p></section>`:''}<section class="kotoba-example-section"><span class="kotoba-kicker">LIHAT PEMAKAIANNYA</span><h2>Contoh kalimat sederhana</h2>${e.example?`<div class="kotoba-example"><p lang="ja" class="kotoba-example-jp">${esc(e.example.jp)}</p><p lang="ja" class="kotoba-example-kana">${esc(e.example.kana)}</p><p class="kotoba-example-romaji">${esc(bunpoExampleRomaji(e.example.kana))}</p><details class="kotoba-translation"><summary>Buka arti kalimat</summary><p>${esc(e.example.meaning)}</p></details></div>`:'<p class="kotoba-custom-note">Contoh kalimat belum tersedia untuk kata ini.</p>'}</section>${kotobaSenseDetails(e)}${e.note?`<section class="kotoba-note"><span>✦</span><div><h2>Catatan kecil</h2><p>${esc(e.note)}</p></div></section>`:''}${e.aliases.length||e.readings.length>1?`<details class="kotoba-variants"><summary>Variasi penulisan & bacaan</summary><p>${esc([...new Set([...e.aliases,...e.readings])].join(' · '))}</p><small>Variasi ini digabung dalam satu kartu; makna dan pemakaian dapat mengikuti konteks.</small></details>`:''}<button class="kana-back-bottom" onclick="appBack()">‹ Kembali ke daftar Kotoba</button>${next?`<button class="kotoba-next" onclick="openKotoba('${next.id}',true)"><small>Kata berikutnya</small><span lang="ja">${esc(next.jp)} <b>→</b></span></button>`:''}</article>`}
